/* Original textbook excerpts and independently written revision aids. */
window.createSignalReference = function({D,escape,md,heading,options,referenceGallery,questionLabel}) {
 const cards=D.referenceHandbook?.cards||[];
 const categories=[['definition','定义','#1f5d9b'],['formula','公式','#6c41a5'],['property','性质','#087b7e'],['table','变换表','#946009'],['common','常规解法','#317247'],['special','特殊技巧','#ae3864']];
 const categoryById=new Map(categories.map(c=>[c[0],c]));
 const originals=new Map((D.textbookReferences?.handbookCards||[]).map(c=>[c.id,c]));
 const concepts=new Map((D.textbookReferences?.concepts||[]).map(c=>[c.id,c]));
 const byId=new Map(cards.map(c=>[c.id,c]));
 const name=id=>categoryById.get(id)?.[1]||'复习卡';
 const allCategories=[['','全部'],...categories];
 const blocks=(title,value,kind)=>value?`<section class="reference-aid ${kind}"><h2>${title}</h2>${md(Array.isArray(value)?value.map(x=>'- '+x).join('\n'):value)}</section>`:'';
 function examples(c){return `<div class="reference-examples"><h2>用到这张卡的题目</h2><p class="muted">点击直接进入题内解析；真题会定位到多方法对照。</p><div class="inline-actions">${(c.exampleIds||[]).map(id=>`<button data-action="open-analysis" data-id="${escape(id)}">${escape(questionLabel(id))} →</button>`).join('')}</div></div>`;}
 function diagrams(c){return (c.diagramPaths||[]).map(p=>`<figure class="figure reference-diagram"><img src="${escape(p.startsWith('assets/')?p:'assets/'+p)}" alt="${escape(c.title)} · 中文图解" loading="lazy" data-expand><figcaption>中文辅助图 · 独立绘制，用于理解原书公式</figcaption></figure>`).join('');}
 function original(c){
  const refs=[originals.get(c.id),...(c.conceptIds||[]).map(id=>concepts.get(id))].filter(Boolean);
  if(!refs.length)return '';
  return `<details class="reference-original reference-fold"><summary>原书扫描图与页码（展开对照）</summary><div class="reference-fold-content">${refs.map(r=>`<section><p class="book-citation">${escape(r.section||c.section||'原教材相关基础')} · 书页 ${(r.printPages||[]).join('、')}；各图另标PDF页码。</p>${referenceGallery(r.excerpts,'教材原文')}${r.displayNote?`<p class="source-note">${escape(r.displayNote)}</p>`:''}</section>`).join('')}</div></details>`;
 }
 function clearTable(c){
  const table=c.clearTable;if(!table)return '';
  const core=table.rows.filter(r=>r.core).length,total=table.rows.length;
  return `<section class="clear-transform-panel" aria-labelledby="clear-table-title-${escape(c.id)}"><div class="clear-table-heading"><h2 id="clear-table-title-${escape(c.id)}">清晰排版对照</h2><span>常用 ${core} / 完整 ${total} 行</span></div><div class="clear-table-notation">${md(table.compactNote||table.notation||'')}</div><div class="clear-table-scroll"><table class="clear-transform-table" id="clear-table-${escape(c.id)}"><thead><tr>${table.columns.map(label=>`<th scope="col">${escape(label)}</th>`).join('')}</tr></thead><tbody>${table.rows.map(row=>`<tr ${row.core?'':'data-reference-extra hidden'}>${row.cells.map((cell,i)=>`<td><div class="clear-cell-label">${md(table.columns[i])}</div><div class="clear-cell">${md(cell)}</div></td>`).join('')}</tr>`).join('')}</tbody></table></div>${core<total?`<button class="clear-table-toggle" data-action="toggle-reference-table" data-core="${core}" data-total="${total}" aria-expanded="false" aria-controls="clear-table-${escape(c.id)}">显示完整对照表（${total}行） ↓</button>`:''}<div class="clear-table-note"><button class="plain clear-table-note-toggle" data-action="toggle-reference-notes" aria-expanded="false" aria-controls="clear-notes-${escape(c.id)}">完整符号约定与原表说明 ▾</button><div class="clear-table-note-body" id="clear-notes-${escape(c.id)}" hidden>${md(table.notation)}<p class="clear-table-source">${escape(table.sourceNote)}</p></div></div></section>`;
 }
 function detail(c){
  const index=cards.indexOf(c),isMethod=['common','special'].includes(c.category),hasTable=!!c.clearTable;
  const explanation=isMethod?blocks('怎么做 · 逐步路线',c.explanation,'reference-understanding'):'';
  const aids=(isMethod?'':blocks('怎么理解',c.explanation,'reference-understanding'))+blocks(isMethod?'第一步怎么想到':'记忆提示',c.memory,'reference-memory')+(hasTable?blocks('补充适用条件',c.conditions,'reference-conditions'):'')+blocks('易错提醒',c.pitfalls,'reference-warning');
  return `<div class="reference-toolbar reference-toolbar-compact"><a class="button" href="#reference?category=${c.category}">← ${name(c.category)}目录</a><button data-action="print-guide">打印 / PDF</button><details class="reference-tools"><summary>更多资料</summary><a href="#digest?chapter=${c.chapter}">本章精读提要 →</a><a href="downloads/reference-handbook.pdf" download>原图版速查手册 ↓</a></details></div><article class="reference-detail ref-${c.category}"><header class="reference-detail-head"><span class="reference-label">${name(c.category)}</span><span class="muted">${c.chapter==='S'?'补充专题':'第'+escape(c.chapter)+'章'}</span><h1>${escape(c.title)}</h1>${hasTable?'':`<p>${isMethod?'先看关键关系与步骤，原书和补充提示按需展开。':'清晰公式连同条件一起看，原书与理解提示按需展开。'}</p>`}</header><div class="reference-reading">${original(c)}${hasTable?clearTable(c):blocks(isMethod?'关键关系':'清晰公式',c.formula,'reference-formula')}${explanation}${hasTable?'':blocks('适用条件',c.conditions,'reference-conditions')}${aids?`<details class="reference-fold reference-extra-aids"><summary>理解、记忆与易错点</summary><div class="reference-fold-content">${aids}</div></details>`:''}<details class="reference-fold reference-extra-examples"><summary>${c.diagramPaths?.length?'辅助图形与配套题目':'配套题目'}</summary><div class="reference-fold-content">${diagrams(c)}${examples(c)}</div></details></div></article><div class="reference-toolbar">${index>0?`<a class="button" href="#reference?card=${cards[index-1].id}">← 上一张</a>`:'<span></span>'}${index<cards.length-1?`<a class="button" href="#reference?card=${cards[index+1].id}">下一张 →</a>`:''}</div>`;
 }
 return function reference(p){
  if(byId.has(p.get('card')))return detail(byId.get(p.get('card')));
  const category=p.get('category')||'',chapter=p.get('chapter')||'',query=p.get('q')||'';
  const list=cards.filter(c=>(!category||c.category===category)&&(!chapter||String(c.chapter)===chapter)&&(!query||[c.title,c.formula,c.explanation,c.memory,JSON.stringify(c.clearTable||{}),...(c.keywords||[])].join(' ').toLowerCase().includes(query.toLowerCase())));
  return heading('教材原图 / 公式 / 方法','把常用的，放在手边','定义、傅里叶级数、四类变换、性质与真题解法放在一起查。清晰公式直接查，原书与补充提示按需展开，点击题号可进入真题。')+`<div class="inline-actions"><a class="button" href="#digest">先读原书精简主线 →</a></div><section class="reference-intro"><div><strong>${cards.length} 张复习卡</strong><p>蓝色看定义，紫色看公式，青色看性质，金色查变换表，绿色选常规解法，玫红色找特殊技巧。</p></div><a class="button" href="downloads/reference-handbook.pdf" download>下载彩色速查 PDF ↓</a></section><div class="reference-categories" role="group" aria-label="速查分类">${allCategories.map(([id,label])=>`<a class="reference-category ref-${id||'all'} ${id===category?'selected':''}" href="#reference${id?'?category='+id:''}">${label}<span>${cards.filter(c=>!id||c.category===id).length}</span></a>`).join('')}</div><details class="reference-notation"><summary>先分清记号：$j\\omega$ 与 $e^{j\\omega}$，级数与变换</summary><div class="lesson">${md(D.referenceHandbook?.notation||'')}</div></details><div class="filters"><input id="reference-search" aria-label="搜索速查" placeholder="搜索：冲激、对偶、抽样、ROC、第一步…" value="${escape(query)}"><select id="reference-chapter" aria-label="速查章节">${options(D.chapters.map(c=>[c.chapter,(c.chapter==='S'?'补充':c.chapter+'章')+' '+c.name]),chapter,'全部章节')}</select><a class="button" href="#reference?category=table">直达变换表 →</a></div><div class="section-head"><h2>${list.length} 张${category?name(category):'复习'}卡</h2><span class="muted">打开卡片查看清晰公式与条件</span></div><div class="reference-grid">${list.map(c=>`<a class="reference-index-card ref-${c.category}" href="#reference?card=${c.id}"><div class="reference-card-meta"><span class="reference-label">${name(c.category)}</span><span>${c.chapter==='S'?'补充专题':'第'+escape(c.chapter)+'章'}</span></div><h3>${escape(c.title)}</h3><div class="reference-card-summary">${md(c.preview||c.memory)}</div><span class="reference-card-foot">${['common','special'].includes(c.category)?'看解题步骤与真题示例':'查清晰公式与原书对照'} →</span></a>`).join('')||'<p class="empty">没有匹配的卡片，换个关键词试试。</p>'}</div>`;
 };
};
